var ANIM = [], CURSCENE = null, MIN_STAND = 8, NOANIM = false;   // NOANIM: Kamera-Grundbewegung (Punch-Out ueber den Schnitt ist gewollt)   // fertiger Zustand steht mindestens 8 Frames
