    keys(C.property("ADBE Vector Graphic - Stroke").property("ADBE Vector Stroke Width"), [t, t + 1.0], [8, 0.5], 40);
    keys(G.property("ADBE Vector Transform Group").property("ADBE Vector Group Opacity"), [t, t + 1.0], [100, 0], 40);
