  var g = grp(ln, "Linie"); addPath(g, line2([[x1, -2], [WX(-400), 3], [x0, 0]])); stroke(g, INK, 12);
  var tk = shape(c, "Zeitstrahl Striche"); place(tk, par, [0, 0]);
