  var gh = grp(p, "Kopf"); ellipseG(gh, 46, 46, 14, -108); fill(gh, color || RED); stroke(gh, INK, 3);
  var gl = grp(p, "Glanz"); ellipseG(gl, 12, 12, 6, -116); fill(gl, "#FFFFFF", 85);
